{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.plasmate-labs/plasmate",
  "title": "Plasmate",
  "description": "Agent-native headless browser. HTML in, Semantic Object Model out. 17x token compression.",
  "repository": {
    "url": "https://github.com/plasmate-labs/plasmate",
    "source": "github"
  },
  "version": "0.4.0",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "plasmate",
      "version": "0.4.0",
      "runtimeHint": "npx",
      "transport": {
        "type": "stdio"
      },
      "arguments": [
        {
          "type": "positional",
          "value": "mcp",
          "isRequired": true
        }
      ]
    },
    {
      "registryType": "pypi",
      "identifier": "plasmate",
      "version": "0.4.1",
      "runtimeHint": "uvx",
      "transport": {
        "type": "stdio"
      },
      "arguments": [
        {
          "type": "positional",
          "value": "mcp",
          "isRequired": true
        }
      ]
    }
  ]
}
